insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('breakouts-before-photos', null, 'Breakouts before photos', $body$I used to cancel plans when I woke up with a new breakout. Group photos were the worst: I would stand at the edge, chin tilted down, already apologising in my head. Last month my cousin's engagement came around and I decided to just go. I covered what I wanted to cover and left the rest. Nobody looked at my chin the way I did. Looking at the photos later, what I noticed was my own smile, which I had not seen in a picture for a long time.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '0 days', timestamptz '2026-10-01 09:00:00+00' + interval '0 days', timestamptz '2026-10-01 09:00:00+00' + interval '0 days')
on conflict (slug) do nothing;
