insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('not-a-shade-to-fix', null, 'Not a shade to fix', $body$Growing up I was told to stay out of the sun, to carry an umbrella to school, to be careful which colours I wore. Nobody said it cruelly. It was just the air in the house. When my grandmother passed, I found her old saris and wore one to a wedding. In the mirror I finally saw her warmth in my own skin and it was not something to correct. I am still unlearning the umbrella, but I am doing it on days I choose.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '1 days', timestamptz '2026-10-01 09:00:00+00' + interval '1 days', timestamptz '2026-10-01 09:00:00+00' + interval '1 days')
on conflict (slug) do nothing;
