insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('where-i-healed', null, 'Where I healed', $body$I had chickenpox at nine and the marks on my forehead became the first thing I covered with a fringe. For years I arranged my hair around them like a curtain. At twenty-two I cut the fringe on a whim and the world did not end. These days I think of those marks as proof that my skin knows how to repair itself. They are not a flaw I am hiding, they are a place where something hurt and then got better.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '2 days', timestamptz '2026-10-01 09:00:00+00' + interval '2 days', timestamptz '2026-10-01 09:00:00+00' + interval '2 days')
on conflict (slug) do nothing;
