insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('the-filter-i-deleted', null, 'The filter I deleted', $body$I deleted the filter app on a Tuesday after catching myself retouching a photo I was only going to send to my sister. It took about a week for my own face to feel familiar again, which says something. Every unfiltered selfie felt wrong and slightly cruel, like a stranger had been swapped in. By the second week it just looked like me. Tired, a bit shiny, and mine.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '3 days', timestamptz '2026-10-01 09:00:00+00' + interval '3 days', timestamptz '2026-10-01 09:00:00+00' + interval '3 days')
on conflict (slug) do nothing;
