insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('melasma-and-mornings', null, 'Melasma and mornings', $body$My patches darken every summer and soften a little in winter, like a tide. For two years I asked the internet how to erase them and came away with a shelf of products and a lot of shame. This year I changed the question. I stopped asking how to get rid of them and started asking how to be gentle with myself while they are here. Mornings are easier now. I wash my face, I say good morning, and I leave it there.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '4 days', timestamptz '2026-10-01 09:00:00+00' + interval '4 days', timestamptz '2026-10-01 09:00:00+00' + interval '4 days')
on conflict (slug) do nothing;
