insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('adult-acne', null, 'Adult acne', $body$Nobody warned me that acne could arrive at thirty. I had survived my teens with clear skin and quietly assumed I was done. Then a new job, new stress, and suddenly I was hiding behind my hair in meetings. What helped was a friend who simply said, me too, and showed me her own jawline without any filter or fuss. I am learning that it is common, that it can be treated, and that it is not a verdict on how I take care of myself.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '5 days', timestamptz '2026-10-01 09:00:00+00' + interval '5 days', timestamptz '2026-10-01 09:00:00+00' + interval '5 days')
on conflict (slug) do nothing;
