insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('scrolling-less', null, 'Scrolling less', $body$I muted every account that made me feel smaller, one by one, without drama. I did not unfollow anyone, because I did not want to make it a statement. I just stopped seeing them. My feed is quieter now and so is my head. I still see beautiful faces, but fewer of them arrive with a quiet instruction attached.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '6 days', timestamptz '2026-10-01 09:00:00+00' + interval '6 days', timestamptz '2026-10-01 09:00:00+00' + interval '6 days')
on conflict (slug) do nothing;
