insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('acne-scars-honestly', null, 'Acne scars, honestly', $body$I spent years chasing perfectly smooth skin and my bathroom drawer shows it. A friend looked at my cheek in daylight and said it looks like the moon, and strangely that stuck. I stopped treating the chase as the goal. Some days I treat my scars, some days I just say hello to them. Both feel like care, and neither one feels like losing.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '7 days', timestamptz '2026-10-01 09:00:00+00' + interval '7 days', timestamptz '2026-10-01 09:00:00+00' + interval '7 days')
on conflict (slug) do nothing;
