insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('seeing-myself-in-colour', null, 'Seeing myself in colour', $body$For a long time I looked for beauty that looked like me and did not find it on the posters, in the films, or in the shop windows. So I started noticing it where it was: in my aunt laughing with her head thrown back, in my cousin's wedding photographs, in my father's hands. After a while the noticing turned inward. I am not there yet, but I can now catch the moment I am about to apologise for my colour and decide not to.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '8 days', timestamptz '2026-10-01 09:00:00+00' + interval '8 days', timestamptz '2026-10-01 09:00:00+00' + interval '8 days')
