insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('a-note-to-keep', null, 'A note to keep', $body$I wrote this on a sticky note and put it on the mirror: the face I see here is a person, not a project. I can let it be here with me today. It does not fix anything. But on mornings when I stand there auditing myself, it reminds me that I am allowed to just brush my teeth and go.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '10 days', timestamptz '2026-10-01 09:00:00+00' + interval '10 days', timestamptz '2026-10-01 09:00:00+00' + interval '10 days')
