insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('the-whole-picture', null, 'The whole picture', $body$I used to look for one mark before I saw anything else in a photo, a patch by my temple that felt like a spotlight. Little by little I am training my eyes to travel. The light on the window behind me. The way my hair does that thing. The people I am with. The mark is still there, but it is no longer the whole picture, and some days I forget to look for it.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '11 days', timestamptz '2026-10-01 09:00:00+00' + interval '11 days', timestamptz '2026-10-01 09:00:00+00' + interval '11 days')
