insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('under-my-eyes', null, 'Under my eyes', $body$Dark circles run in my family, and I have had them since I was a teenager. People kept asking me if I was okay, if I had slept, if I was ill. They meant well, but after the hundredth time I started to hear it as you look wrong. I now answer, I am fine, this is just my face. Saying it out loud, lightly, took some of the sting out of the question.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '12 days', timestamptz '2026-10-01 09:00:00+00' + interval '12 days', timestamptz '2026-10-01 09:00:00+00' + interval '12 days')
