insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('concealer-as-armour', null, 'Concealer as armour', $body$For years I would not leave the house without concealer under my eyes. It was armour, and I do not think that is silly. Armour is useful. What I am practising now is choosing days to go without, such as the supermarket on a Sunday or a walk before work. Nobody has fainted. I am learning which days I want armour and which days I just want to be unguarded and comfortable.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '13 days', timestamptz '2026-10-01 09:00:00+00' + interval '13 days', timestamptz '2026-10-01 09:00:00+00' + interval '13 days')
on conflict (slug) do nothing;
