insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('before-the-video-call', null, 'Before the video call', $body$The small square of my own face in video calls undoes me. I used to spend ten minutes before every meeting staring at it, adjusting the light and my angle. Hiding self-view helped more than any ring light. When I cannot see myself, I can listen. It took me a month to notice that nobody else in the call was studying my face either. They were looking at their own squares too.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '14 days', timestamptz '2026-10-01 09:00:00+00' + interval '14 days', timestamptz '2026-10-01 09:00:00+00' + interval '14 days')
on conflict (slug) do nothing;
