insert into public.stories (slug, author_id, title, content, status, is_anonymous, is_demo_content, created_at, updated_at, published_at)
values ('edited-and-everyone-knew', null, 'Edited, and everyone knew', $body$My friend posted a photo with her skin smoothed and lightened a few shades. Everyone commented how flawless she looked. Weeks later she admitted she had hated that photo because it did not look like her. That was the day I understood how much of what I compare myself to is not real, even to the people in it. Now when I feel the old pull, I ask myself who this picture was made for.$body$, 'published', true, true, timestamptz '2026-10-01 09:00:00+00' + interval '15 days', timestamptz '2026-10-01 09:00:00+00' + interval '15 days', timestamptz '2026-10-01 09:00:00+00' + interval '15 days')
on conflict (slug) do nothing;
